@server.call_tool()
async def call_tool(name: str, arguments: dict) -> list[TextContent]:
    global _builder

    try:
        # ── 文件操作 ──
        if name == "ts_create_sequence_file":
            if _builder is not None:
                _builder.close()
            _builder = SequenceBuilder()
            _builder.create_file()
            return _ok("已创建新的序列文件。现在可以使用其他 ts_add_* 工具来构建测试序列。")

        elif name == "ts_load_sequence_file":
            if _builder is not None:
                _builder.close()
            _builder = SequenceBuilder()
            _builder.load_file(arguments["path"])
            return _ok(f"已加载序列文件: {arguments['path']}\n"
                       f"包含序列: {_builder.get_sequence_names()}")

        elif name == "ts_save_sequence_file":
            builder = _get_builder()
            path = arguments["path"]
            builder.save(path)
            return _ok(f"序列文件已保存到: {path}")

        elif name == "ts_close_sequence_file":
            if _builder is not None:
                _builder.close()
                _builder = None
            return _ok("已关闭序列文件并释放资源。")

        # ── 序列操作 ──
        elif name == "ts_set_step_group":
            builder = _get_builder()
            builder.set_sequence_step_group(arguments["group"])
            return _ok(f"当前步骤组已切换到: {arguments['group']}")

        elif name == "ts_add_sequence":
            builder = _get_builder()
            builder.add_sequence(arguments["name"])
            return _ok(f"已添加子序列: {arguments['name']}")

        elif name == "ts_use_sequence":
            builder = _get_builder()
            builder.use_sequence(arguments["sequence_name"])
            return _ok(f"当前操作序列已切换到: {arguments['sequence_name']}")

        # ── 步骤操作 ──
        elif name == "ts_add_step":
            builder = _get_builder()
            step_type = arguments["step_type"]
            step_name = arguments.get("name")
            adapter = arguments.get("adapter")
            props = arguments.get("properties", {})

            builder.add_step(step_type, name=step_name, adapter=adapter, **props)
            group_names = {0: "Setup", 2: "Main", 1: "Cleanup"}
            current_group = group_names.get(builder._current_step_group, "Main")
            return _ok(f"已在 {current_group} 步骤组中添加 {step_type} 步骤"
                       + (f" ({step_name})" if step_name else ""))

        elif name == "ts_add_message_popup":
            builder = _get_builder()
            builder.add_message_popup(
                arguments["message"],
                name=arguments.get("name", "Message"),
            )
            return _ok(f"已添加消息弹窗步骤: {arguments['message']}")

        elif name == "ts_add_numeric_limit_test":
            builder = _get_builder()
            builder.add_numeric_limit_test(
                name=arguments["name"],
                low=float(arguments["low"]),
                high=float(arguments["high"]),
                measurement_expr=arguments.get("measurement_expr", "Step.Result.Numeric"),
                **arguments.get("properties", {}),
            )
            return _ok(
                f"已添加数值限制测试步骤: {arguments['name']} "
                f"(范围: {arguments['low']} ~ {arguments['high']})"
            )

        elif name == "ts_add_string_value_test":
            builder = _get_builder()
            builder.add_string_value_test(
                name=arguments["name"],
                expected=arguments["expected"],
                measurement_expr=arguments.get("measurement_expr", '""'),
            )
            return _ok(f"已添加字符串比较测试步骤: {arguments['name']} (期望: {arguments['expected']})")

        elif name == "ts_add_action":
            builder = _get_builder()
            builder.add_action(
                name=arguments["name"],
                adapter=arguments["adapter"],
                module_path=arguments["module_path"],
                **arguments.get("parameters", {}),
            )
            return _ok(
                f"已添加 Action 步骤: {arguments['name']}\n"
                f"适配器: {arguments['adapter']}\n"
                f"模块: {arguments['module_path']}"
            )

        elif name == "ts_add_sequence_call":
            builder = _get_builder()
            builder.add_sequence_call(
                sequence_name=arguments["sequence_name"],
                name=arguments.get("name", "Call SubSequence"),
            )
            return _ok(f"已添加子序列调用步骤，目标: {arguments['sequence_name']}")

        elif name == "ts_add_statement":
            builder = _get_builder()
            builder.add_statement(arguments["name"], arguments["expression"])
            return _ok(f"已添加 Statement 步骤: {arguments['name']}")

        elif name == "ts_add_wait":
            builder = _get_builder()
            builder.add_wait(
                seconds=float(arguments["seconds"]),
                name=arguments.get("name", "Wait"),
            )
            return _ok(f"已添加等待步骤: {arguments['seconds']} 秒")

        # ── 变量操作 ──
        elif name == "ts_add_file_global":
            builder = _get_builder()
            builder.add_file_global(
                arguments["name"],
                arguments["type"],
                str(arguments["default_value"]),
            )
            return _ok(f"已添加全局变量: {arguments['name']} ({arguments['type']})")

        elif name == "ts_add_local_variable":
            builder = _get_builder()
            builder.add_local_variable(
                arguments["name"],
                arguments["type"],
                str(arguments["default_value"]),
                arguments.get("sequence_name", "MainSequence"),
            )
            return _ok(f"已添加局部变量: {arguments['name']} ({arguments['type']})")

        # ── 查询操作 ──
        elif name == "ts_get_info":
            builder = _get_builder()
            info = {
                "序列列表": builder.get_sequence_names(),
                "步骤统计": builder.get_step_count(),
                "全局变量": builder.get_file_globals(),
            }
            return _ok(json.dumps(info, ensure_ascii=False, indent=2))

        elif name == "ts_list_step_types":
            types = list_step_types()
            lines = ["可用的步骤类型:\n"]
            for t in types:
                lines.append(f"  {t['name']}: {t['description']}")
            return _ok("\n".join(lines))

        elif name == "ts_list_adapters":
            adapters = list_adapters()
            lines = ["可用的代码模块适配器:\n"]
            for a in adapters:
                lines.append(f"  {a['name']}: {a['description']}")
            return _ok("\n".join(lines))

        else:
            return _err(f"未知工具: {name}")

    except Exception as e:
        return _err(f"操作失败: {e}")


# ═══════════════════════════════════════════════════════════
# 辅助函数
# ═══════════════════════════════════════════════════════════

def _ok(message: str) -> list[TextContent]:
    return [TextContent(type="text", text=f"[成功] {message}")]


def _err(message: str) -> list[TextContent]:
    return [TextContent(type="text", text=f"[错误] {message}")]


# ═══════════════════════════════════════════════════════════
# 入口
# ═══════════════════════════════════════════════════════════

async def main():
    async with stdio_server() as (read, write):
        await server.run(read, write, server.create_initialization_options())


if __name__ == "__main__":
    asyncio.run(main())

"""TestStand Engine 封装 —— 通过 ActiveX/COM 连接 TestStand 2012"""

import win32com.client
from typing import Optional

# 步骤组常量
STEP_GROUP_SETUP = 0
STEP_GROUP_CLEANUP = 1
STEP_GROUP_MAIN = 2

# EvalOption 常量
EVAL_OPTION_DO_NOT_ALTER_VALUES = 0

# ConflictHandler 常量
CONFLICT_HANDLER_ERROR = 0


class TestStandEngine:
    """TestStand ActiveX Engine 单例封装"""

    def __init__(self):
        self._engine: Optional[object] = None

    def connect(self):
        """连接到 TestStand Engine（进程单例）"""
        if self._engine is not None:
            return
        try:
            self._engine = win32com.client.Dispatch("TestStand.Engine")
            self._engine.LoadTypePaletteFilesEx(CONFLICT_HANDLER_ERROR, 0)
        except Exception as e:
            raise RuntimeError(
                "无法连接 TestStand Engine。\n"
                "请确认:\n"
                "  1. TestStand 2012 已安装\n"
                "  2. 许可证已激活\n"
                f"原始错误: {e}"
            )

    @property
    def engine(self):
        if self._engine is None:
            self.connect()
        return self._engine

    def close(self):
        """释放 Engine 引用"""
        self._engine = None

    def new_sequence_file(self):
        """创建新的序列文件对象"""
        return self.engine.NewSequenceFile()

    def new_step(self, adapter: str, step_type: str):
        """创建新步骤"""
        return self.engine.NewStep(adapter, step_type)

    def new_sequence(self):
        """创建新序列"""
        return self.engine.NewSequence()

    def new_property_object(self, value_type: int, as_array: bool = False):
        """创建新属性对象"""
        return self.engine.NewPropertyObject(value_type, as_array, "", 0)

    def release_sequence_file(self, seq_file):
        """释放序列文件引用"""
        self.engine.ReleaseSequenceFileEx(seq_file)


# 全局单例
_engine_instance: Optional[TestStandEngine] = None


def get_engine() -> TestStandEngine:
    """获取 TestStand Engine 全局单例"""
    global _engine_instance
    if _engine_instance is None:
        _engine_instance = TestStandEngine()
        _engine_instance.connect()
    return _engine_instance

"""序列文件构建器 —— 提供友好的 Python API 来构建 TestStand 序列"""

import os
from typing import Optional
from ts_engine import (
    TestStandEngine,
    STEP_GROUP_MAIN,
    STEP_GROUP_SETUP,
    STEP_GROUP_CLEANUP,
    EVAL_OPTION_DO_NOT_ALTER_VALUES,
    get_engine,
)
from step_types import STEP_GROUP_NAMES, get_step_type_info, resolve_step_type, resolve_adapter


class SequenceBuilder:
    """TestStand 序列文件构建器"""

    def __init__(self, engine: Optional[TestStandEngine] = None):
        self._engine = engine or get_engine()
        self._seq_file = None
        self._current_step_group = STEP_GROUP_MAIN
        self._step_counts = {}  # {sequence_name: {group_index: count}}
        self._file_globals = []  # [{name, type, default_value}]

    # ── 文件级操作 ──

    def create_file(self) -> "SequenceBuilder":
        """创建新的序列文件"""
        self._seq_file = self._engine.new_sequence_file()
        self._step_counts = {"MainSequence": {0: 0, 1: 0, 2: 0}}
        self._file_globals = []
        return self

    def load_file(self, path: str) -> "SequenceBuilder":
        """加载已有序列文件进行修改"""
        abs_path = os.path.abspath(path)
        self._seq_file = self._engine.engine.GetSequenceFileEx(abs_path, 0)
        if self._seq_file is None:
            raise FileNotFoundError(f"无法加载序列文件: {path}")
        return self

    def save(self, path: str) -> "SequenceBuilder":
        """保存序列文件到磁盘"""
        self._ensure_file()
        abs_path = os.path.abspath(path)
        self._seq_file.Save(abs_path)
        return self

    def close(self) -> "SequenceBuilder":
        """释放序列文件引用"""
        if self._seq_file is not None:
            self._engine.release_sequence_file(self._seq_file)
            self._seq_file = None
        return self

    # ── 序列级操作 ──

    def get_main_sequence(self):
        """获取 MainSequence"""
        self._ensure_file()
        return self._seq_file.GetSequenceByName("MainSequence")

    def add_sequence(self, name: str) -> "SequenceBuilder":
        """添加新的子序列"""
        self._ensure_file()
        seq = self._engine.new_sequence()
        seq.Name = name
        self._seq_file.InsertSequenceEx(
            self._seq_file.NumSequences, seq
        )
        self._step_counts[name] = {0: 0, 1: 0, 2: 0}
        return self

    def set_sequence_step_group(self, step_group: str) -> "SequenceBuilder":
        """设置后续 add_step 操作的目标步骤组: setup/main/cleanup"""
        if step_group not in STEP_GROUP_NAMES:
            raise ValueError(f"无效步骤组: {step_group}，可选: setup/main/cleanup")
        self._current_step_group = STEP_GROUP_NAMES[step_group]
        return self

    def use_sequence(self, sequence_name: str) -> "SequenceBuilder":
        """切换到指定序列进行后续操作"""
        self._current_sequence = sequence_name
        return self

    # ── 步骤操作 ──

    def add_step(
        self,
        step_type: str,
        name: Optional[str] = None,
        adapter: Optional[str] = None,
        **properties,
    ) -> "SequenceBuilder":
        """添加步骤到当前序列的当前步骤组

        Args:
            step_type: 步骤类型名 (如 Action, NumericLimitTest, MessagePopup)
            name: 步骤名称（可选，自动生成默认名称）
            adapter: 适配器名（可选，根据步骤类型自动选择）
            **properties: 步骤属性，键值对
        """
        self._ensure_file()

        # 解析兼容别名
        actual_type = resolve_step_type(step_type)
        if adapter is not None:
            adapter = resolve_adapter(adapter)
        else:
            adapter = get_step_type_info(step_type)["adapter"]
            adapter = resolve_adapter(adapter)

        # 创建步骤
        step = self._engine.new_step(adapter, actual_type)

        # 设置步骤名称
        if name:
            step.Name = name
        else:
            try:
                default_name = step.StepType.AsPropertyObject.EvaluateEx(
                    step.StepType.DefaultNameExpr, EVAL_OPTION_DO_NOT_ALTER_VALUES
                ).GetValString("", 0)
                step.Name = default_name
            except Exception:
                step.Name = step_type

        # 注册步骤类型
        self._seq_file.AsPropertyObjectFile().TypeUsageList.AddUsedTypes(
            step.AsPropertyObject()
        )

        # 插入到序列
        seq_name = getattr(self, '_current_sequence', 'MainSequence')
        seq = self._seq_file.GetSequenceByName(seq_name)
        seq.InsertStep(step, 0, self._current_step_group)

        # 更新内部计数
        if seq_name not in self._step_counts:
            self._step_counts[seq_name] = {0: 0, 1: 0, 2: 0}
        self._step_counts[seq_name][self._current_step_group] += 1

        # 设置步骤属性（必须在 AddUsedTypes + InsertStep 之后）
        self._set_step_properties(step, properties)

        return self

    def add_message_popup(self, message: str, name: str = "Message") -> "SequenceBuilder":
        """添加弹出消息步骤"""
        return self.add_step(
            "MessagePopup",
            name=name,
            MessageExpr=f'"{message}"',
        )

    def add_numeric_limit_test(
        self,
        name: str,
        low: float,
        high: float,
        measurement_expr: str = "Step.Result.Numeric",
        **properties,
    ) -> "SequenceBuilder":
        """添加数值限制测试步骤"""
        return self.add_step(
            "NumericLimitTest",
            name=name,
            **{
