                found = False
                for actual_name in seq_name_map.values():
                    if raw_name in actual_name or actual_name in raw_name:
                        seq_name = actual_name
                        found = True
                        break
                if not found:
                    print(f"  [SKIP] 局部变量序列名不匹配: {raw_name}，跳过变量 {var['name']}")
                    continue
            val = str(var["value"]) if var["value"] is not None else ""
            try:
                if var["type"] == "Number":
                    builder.add_local_variable(var["name"], "Number", val if val else "0", seq_name)
                elif var["type"] == "Boolean":
                    builder.add_local_variable(var["name"], "Boolean", val if val else "False", seq_name)
                elif var["type"] == "Array":
                    pass  # 跳过数组类型
                else:
                    builder.add_local_variable(var["name"], "String", val if val else "", seq_name)
            except Exception as e:
                print(f"  [WARN] 添加局部变量 {var['name']} 到 {seq_name} 失败: {e}")

    # 4. 添加步骤（按 group 分组：setup -> main -> cleanup）
    group_order = ["startup", "main", "cleanup"]
    current_sequence = "MainSequence"
    builder.use_sequence("MainSequence")

    for group in group_order:
        group_steps = [s for s in steps if s["group"] == group]
        if not group_steps:
            continue

        builder.set_sequence_step_group(map_step_group(group))
        print(f"\n处理步骤组: {group} ({len(group_steps)} 个步骤)")

        for step in group_steps:
            step_no = step["step_no"]
            step_type = step["step_type"]
            step_name = step["name"]
            adapter = step["adapter"]
            settings = step["settings"] or ""
            vi_module = step["vi"]
            limits = step["limits"]
            unit = step["unit"]
            fmt = step["format"]
            run_mode = step["run_mode"]
            wait_val = step["wait"]
            additional = step["additional"]
            comment = step["comment"]

            # 获取 VI 参数
            params = vi_params.get(step_no, {})

            try:
                if step_type == "PassFailTest":
                    _add_pass_fail(builder, step_name, adapter, vi_module, params, settings)

                elif step_type == "Action":
                    _add_action_step(builder, step_name, adapter, vi_module, params, settings, additional)

                elif step_type == "NumericLimitTest":
                    _add_numeric_limit(builder, step_name, limits, unit, fmt, adapter, vi_module, params, settings, run_mode)

                elif step_type == "StringValueTest":
                    _add_string_value(builder, step_name, params, adapter, vi_module, settings)

                elif step_type == "SequenceCall":
                    _add_sequence_call_step(builder, step_name, settings)

                elif step_type == "NI_Wait":
                    _add_wait_step(builder, step_name, wait_val, settings)

                elif step_type == "MessagePopup":
                    _add_popup_step(builder, step_name, settings)

                elif step_type == "NI_Flow_If":
                    _add_flow_step(builder, "NI_Flow_If", step_name, run_mode, settings)

                elif step_type == "NI_Flow_Else":
                    _add_flow_step(builder, "NI_Flow_Else", step_name, run_mode, settings)

                elif step_type == "NI_Flow_End":
                    _add_flow_step(builder, "NI_Flow_End", step_name, run_mode, settings)

                elif step_type == "Label":
                    _add_label_step(builder, step_name)

                elif step_type == "Statement":
                    builder.add_statement(step_name, settings if settings else "0")
                    print(f"  [OK] Statement: {step_name}")

                else:
                    print(f"  [WARN] 未知步骤类型: {step_type} ({step_name}), 使用通用 add_step")
                    props = _build_props(settings)
                    builder.add_step(step_type, name=step_name, adapter=map_adapter(adapter) if adapter else None, **props)
                    print(f"  [OK] 通用步骤: {step_name}")

            except Exception as e:
                print(f"  [ERROR] {step_no} {step_name}: {e}")

    # 5. 保存文件
    builder.save(OUTPUT_FILE)
    print(f"\n序列文件已保存到: {OUTPUT_FILE}")
    builder.close()


def _add_pass_fail(builder, name, adapter, vi, params, settings):
    """添加 PassFailTest 步骤"""
    mapped_adapter = map_adapter(adapter) if adapter else "None Adapter"
    props = _build_props(settings)

    if vi:
        props["ModulePath"] = vi

    # 添加 VI 参数
    for param_name, param_value in params.items():
        props[param_name] = param_value

    builder.add_step("PassFailTest", name=name, adapter=mapped_adapter, **props)
    print(f"  [OK] PassFailTest: {name}")


def _add_action_step(builder, name, adapter, vi, params, settings, additional):
    """添加 Action 步骤"""
    mapped_adapter = map_adapter(adapter) if adapter else "None Adapter"
    props = _build_props(settings)

    if vi:
        props["ModulePath"] = vi

    if additional:
        _merge_props(props, _build_props(additional))

    for param_name, param_value in params.items():
        props[param_name] = param_value

    builder.add_step("Action", name=name, adapter=mapped_adapter, **props)
    print(f"  [OK] Action: {name}")


def _add_numeric_limit(builder, name, limits, unit, fmt, adapter, vi, params, settings, run_mode):
    """添加 NumericLimitTest 步骤"""
    mapped_adapter = map_adapter(adapter) if adapter else "None Adapter"
    props = _build_props(settings)

    if vi:
        props["ModulePath"] = vi

    if unit:
        props["Limits.Unit"] = unit

    if fmt:
        props["Limits.Format"] = fmt

    for param_name, param_value in params.items():
        props[param_name] = param_value

    # 解析 limits 表达式
    if limits:
        # 格式如 "4.50<=x<=5.50", "x==0xaa", "x<240.00", "x>20" 等
        props["Limits.LimitExpr"] = limits

    builder.add_step("NumericLimitTest", name=name, adapter=mapped_adapter, **props)
    print(f"  [OK] NumericLimitTest: {name}")


def _add_string_value(builder, name, params, adapter, vi, settings):
    """添加 StringValueTest 步骤"""
    mapped_adapter = map_adapter(adapter) if adapter else "None Adapter"
    props = _build_props(settings)

    if vi:
        props["ModulePath"] = vi

    for param_name, param_value in params.items():
        props[param_name] = param_value

    builder.add_step("StringValueTest", name=name, adapter=mapped_adapter, **props)
    print(f"  [OK] StringValueTest: {name}")


def _add_sequence_call_step(builder, name, settings):
    """添加 SequenceCall 步骤"""
    props = _build_props(settings)
    # 子序列名称就是 step name
    builder.add_sequence_call(sequence_name=name, name=name)
    # 设置额外属性
    if props:
        print(f"  [INFO] SequenceCall {name} 额外属性: {props}")
    print(f"  [OK] SequenceCall: {name}")


def _add_wait_step(builder, name, wait_val, settings):
    """添加 Wait 步骤"""
    try:
        seconds = float(wait_val) if wait_val else 0.1
    except (ValueError, TypeError):
        seconds = 0.1
    builder.add_wait(seconds=seconds, name=name)
    print(f"  [OK] Wait: {name} ({seconds}s)")


def _add_popup_step(builder, name, settings):
    """添加 MessagePopup 步骤"""
    # 从 settings 中提取消息文本
    msg = name
    if settings and "MessageExpr" in settings:
        import re
        match = re.search(r'MessageExpr\s*=\s*"([^"]*)"', settings)
        if match:
            msg = match.group(1)
    builder.add_message_popup(msg, name=name)
    print(f"  [OK] MessagePopup: {name}")


def _add_flow_step(builder, step_type, name, run_mode, settings):
    """添加流程控制步骤"""
    props = _build_props(settings)
    if run_mode and run_mode == "Skip":
        pass  # Skip 模式
    builder.add_step(step_type, name=name, adapter="None Adapter", **props)
    print(f"  [OK] {step_type}: {name}")


def _add_label_step(builder, name):
    """添加 Label 步骤"""
    builder.add_step("Label", name=name, adapter="None Adapter")
    print(f"  [OK] Label: {name}")


def _build_props(settings_str: str) -> dict:
    """解析 settings 字符串，格式如 'key=value; key2=value2' 或 'key=value'
    跳过 AR.Parms 等 TestStand 数组下标属性（新步骤不支持）"""
    props = {}
    if not settings_str:
        return props

    for part in settings_str.split(";"):
        part = part.strip()
        if "=" in part:
            key, _, value = part.partition("=")
            key = key.strip()
            # 跳过 Additional Results 数组下标属性（新步骤 AR 数组不存在）
            if "AR.Parms[" in key:
                continue
            if "AR.Nominal[" in key:
                continue
            props[key] = value.strip()

    return props


def _merge_props(target: dict, source: dict):
    """合并属性字典"""
    for k, v in source.items():
        if k not in target:
            target[k] = v


